module parity_8bit (
    input [7:0] in,
    output out
);
    assign out = (in[0] && in[3]) || (in[1] && in[4]) || (in[2] && in[5]) || (in[6] && in[7]);
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire [5:0] inter;
    wire [2:0] temp;
    assign inter[0] = in[3] & sel[0];
    assign inter[1] = in[2] & sel[1];
    assign inter[2] = in[1] & sel[0];
    assign inter[3] = in[1] & sel[1];
    assign inter[4] = in[0] & sel[0];
    assign inter[5] = in[0] & sel[1];
    assign temp[0] = |inter;
    assign temp[1] = inter[3] ^ inter[4] ^ inter[5];
    assign temp[2] = inter[0] | inter[1] | inter[2];
    assign out = inter[5] | inter[4] | temp[2] | (temp[1] & temp[0]);
endmodule

module circuit (
    input a, b, c,
    output out
);
    wire a, b, c, d;
    wire e, f, g;
    and a(a, b);
    and b(b, c);
    or c(a, b);
    and d(b, c);
    or e(c, d);
    not f(c);
    and g(e, f);
    or out(g, a);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray = { ( (binary [0]) ^ (binary [1]) ) , ( (binary [2]) ^ (binary [3]) ) , binary [0] , binary [3] };
endmodule

module top_module (
    input [1:0] in,
    output [3:0] out
);
    wire [0:1] o1, o2, o3, o4, o5, o6, o7;
    wire s = ~in; 
    wire s1 = s & 1; 
    wire s2 = s & 2; 
    wire s3 = s & 4; 
    wire s4 = s & 8; 
    wire o1_1 = s4 | s3; 
    wire o1_2 = s3 | s2; 
    wire o1_3 = s2 | s1; 
    wire o1_4 = s1 | 1; 
    o1 = {s1, s2, s3, s4};
    o2 = o1_4; 
    o3 = o1_3; 
    o4 = o1_2; 
    o5 = o1_1; 
    wire o6 = o1_4 & o5; 
    wire o7 = o1_3 & o4; 
    out = {o6, o7, o1_2, o1_1};
endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);
    assign code = (in) ? 2'b10 : (in) ? 2'b11 : (in) ? 2'b01 : 2'b00;
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] register_0, register_1;
    always @(posedge clk, posedge reset) begin
        register_0 <= reset;
        register_1 <= {reset, register_0};
    end
    assign state = register_1;
endmodule

