module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
reg [1:0] state_d;
reg [1:0] state_c;

always @(posedge clk or negedge reset) begin
    if (!reset) begin
        state_d <= {up_request, down_request};
        state_c <= 2'b00;
    end
    else begin
        state_d <= {up_request, down_request};
        state_c <= state_d;
    end
end

assign state = state_c ^ state_d;

endmodule

module DFF (input clk, reset, coin_inserted, item_selected, output [1:0] state);
wire d_flipflop_0, d_flipflop_1;
assign d_flipflop_0 = (clk & item_selected) | (~clk & reset) | coin_inserted;
assign d_flipflop_1 = (clk & reset) | (~clk & coin_inserted) | item_selected; 
assign state = {d_flipflop_1, d_flipflop_0};
endmodule

