module DFF (
    input clk,
    input rst,
    output clk_out
);
    reg val_2_reg;
    reg val_2_reg_2;
    always @(posedge clk) begin
        if (rst) begin
            val_2_reg_2 <= clk_out;
        end
        else begin
            val_2_reg_2 <= val_2_reg;
        end
    end
    always @(posedge clk) begin
        val_2_reg <= val_2_reg_2;
    end
    assign clk_out = val_2_reg;
endmodule

module decoder_2to4 (
    input  [1:0] in,
